/**
 * GAsTCA Charts - Lightweight Chart Library (replaces Chart.js for offline use)
 * Supports: line, doughnut, bar charts
 * API compatible with Chart.js basics
 */

class Chart {
  static defaults = { font: { family: 'Inter, sans-serif' } };
  
  constructor(canvas, config) {
    this.canvas = canvas instanceof HTMLCanvasElement ? canvas : document.getElementById(canvas);
    if (!this.canvas) return;
    
    this.ctx = this.canvas.getContext('2d');
    this.config = config;
    this.type = config.type;
    this.data = config.data;
    this.options = config.options || {};
    
    this.resize();
    this.render();
    
    // Handle resize
    this._resizeObserver = new ResizeObserver(() => this.resize());
    this._resizeObserver.observe(this.canvas.parentElement);
  }

  resize() {
    const parent = this.canvas.parentElement;
    if (parent) {
      this.canvas.width = parent.clientWidth || 400;
      this.canvas.height = parent.clientHeight || 250;
    }
    this.width = this.canvas.width;
    this.height = this.canvas.height;
    this.render();
  }

  render() {
    if (!this.ctx) return;
    this.ctx.clearRect(0, 0, this.width, this.height);
    
    switch (this.type) {
      case 'line': this.renderLine(); break;
      case 'doughnut': this.renderDoughnut(); break;
      case 'bar': this.renderBar(); break;
    }
  }

  renderLine() {
    const { ctx, width, height, data, options } = this;
    const datasets = data.datasets || [];
    const labels = data.labels || [];
    const padding = { top: 20, right: 20, bottom: 40, left: 50 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // Find min/max values
    let allValues = [];
    datasets.forEach(ds => allValues.push(...(ds.data || [])));
    const maxVal = Math.max(...allValues, 1);
    const minVal = Math.min(...allValues, 0);
    const range = maxVal - minVal || 1;

    // Draw grid lines
    ctx.strokeStyle = options?.scales?.y?.grid?.color || 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= 4; i++) {
      const y = padding.top + (chartHeight * i / 4);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      // Y-axis labels
      const val = maxVal - (range * i / 4);
      ctx.fillStyle = options?.scales?.y?.ticks?.color || '#B0B0B0';
      ctx.font = '10px Inter, sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(options?.scales?.y?.ticks?.callback ? options.scales.y.ticks.callback(Math.round(val)) : Math.round(val), padding.left - 8, y + 4);
    }

    // X-axis labels
    ctx.fillStyle = options?.scales?.x?.ticks?.color || '#B0B0B0';
    ctx.font = '10px Inter, sans-serif';
    ctx.textAlign = 'center';
    labels.forEach((label, i) => {
      const x = padding.left + (chartWidth * i / (labels.length - 1 || 1));
      ctx.fillText(label, x, height - 10);
    });

    // Draw datasets
    datasets.forEach(dataset => {
      const points = dataset.data || [];
      if (points.length < 2) return;

      ctx.beginPath();
      ctx.strokeStyle = dataset.borderColor || '#F5A623';
      ctx.lineWidth = dataset.borderWidth || 2;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';

      points.forEach((val, i) => {
        const x = padding.left + (chartWidth * i / (points.length - 1));
        const y = padding.top + chartHeight - ((val - minVal) / range * chartHeight);
        if (i === 0) ctx.moveTo(x, y);
        else {
          if (dataset.tension) {
            const prevX = padding.left + (chartWidth * (i - 1) / (points.length - 1));
            const prevY = padding.top + chartHeight - ((points[i - 1] - minVal) / range * chartHeight);
            const cpX = (prevX + x) / 2;
            ctx.bezierCurveTo(cpX, prevY, cpX, y, x, y);
          } else {
            ctx.lineTo(x, y);
          }
        }
      });
      ctx.stroke();

      // Fill area
      if (dataset.fill) {
        const lastX = padding.left + chartWidth;
        ctx.lineTo(lastX, padding.top + chartHeight);
        ctx.lineTo(padding.left, padding.top + chartHeight);
        ctx.closePath();
        ctx.fillStyle = dataset.backgroundColor || 'rgba(245, 166, 35, 0.1)';
        ctx.fill();
      }

      // Draw points
      const pointRadius = dataset.pointRadius || 0;
      if (pointRadius > 0) {
        points.forEach((val, i) => {
          const x = padding.left + (chartWidth * i / (points.length - 1));
          const y = padding.top + chartHeight - ((val - minVal) / range * chartHeight);
          ctx.beginPath();
          ctx.arc(x, y, pointRadius, 0, Math.PI * 2);
          ctx.fillStyle = dataset.pointBackgroundColor || dataset.borderColor || '#F5A623';
          ctx.fill();
        });
      }
    });
  }

  renderDoughnut() {
    const { ctx, width, height, data, options } = this;
    const dataset = data.datasets?.[0] || {};
    const values = dataset.data || [];
    const colors = dataset.backgroundColor || [];
    const labels = data.labels || [];
    const total = values.reduce((a, b) => a + b, 0) || 1;
    const cutout = parseFloat(options?.cutout || '50%') / 100;
    
    const centerX = width / 2;
    const centerY = height / 2 - 20;
    const outerRadius = Math.min(width, height) / 2 - 40;
    const innerRadius = outerRadius * cutout;

    let startAngle = -Math.PI / 2;

    values.forEach((val, i) => {
      const sliceAngle = (val / total) * Math.PI * 2;
      
      ctx.beginPath();
      ctx.arc(centerX, centerY, outerRadius, startAngle, startAngle + sliceAngle);
      ctx.arc(centerX, centerY, innerRadius, startAngle + sliceAngle, startAngle, true);
      ctx.closePath();
      ctx.fillStyle = colors[i] || '#F5A623';
      ctx.fill();

      startAngle += sliceAngle;
    });

    // Legend
    if (options?.plugins?.legend?.position === 'bottom') {
      const legendY = height - 30;
      const legendColor = options?.plugins?.legend?.labels?.color || '#B0B0B0';
      const fontSize = options?.plugins?.legend?.labels?.font?.size || 11;
      ctx.font = `${fontSize}px Inter, sans-serif`;
      
      let legendX = 10;
      labels.forEach((label, i) => {
        ctx.fillStyle = colors[i] || '#ccc';
        ctx.fillRect(legendX, legendY, 10, 10);
        ctx.fillStyle = legendColor;
        ctx.textAlign = 'left';
        ctx.fillText(label, legendX + 14, legendY + 9);
        legendX += ctx.measureText(label).width + 30;
      });
    }
  }

  renderBar() {
    const { ctx, width, height, data, options } = this;
    const datasets = data.datasets || [];
    const labels = data.labels || [];
    const padding = { top: 20, right: 20, bottom: 40, left: 50 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    let allValues = [];
    datasets.forEach(ds => allValues.push(...(ds.data || [])));
    const maxVal = Math.max(...allValues, 1);

    const barGroupWidth = chartWidth / labels.length;
    const barWidth = barGroupWidth * 0.6 / datasets.length;

    datasets.forEach((dataset, dsIndex) => {
      (dataset.data || []).forEach((val, i) => {
        const x = padding.left + barGroupWidth * i + barGroupWidth * 0.2 + barWidth * dsIndex;
        const barHeight = (val / maxVal) * chartHeight;
        const y = padding.top + chartHeight - barHeight;

        ctx.fillStyle = dataset.backgroundColor?.[i] || dataset.backgroundColor || '#F5A623';
        ctx.beginPath();
        ctx.roundRect(x, y, barWidth - 2, barHeight, [3, 3, 0, 0]);
        ctx.fill();
      });
    });

    // X labels
    ctx.fillStyle = '#B0B0B0';
    ctx.font = '10px Inter, sans-serif';
    ctx.textAlign = 'center';
    labels.forEach((label, i) => {
      const x = padding.left + barGroupWidth * i + barGroupWidth / 2;
      ctx.fillText(label, x, height - 10);
    });
  }

  destroy() {
    if (this._resizeObserver) this._resizeObserver.disconnect();
    if (this.ctx) this.ctx.clearRect(0, 0, this.width, this.height);
  }

  update() {
    this.render();
  }
}

// Make globally available
window.Chart = Chart;
